struct Sha1 {
    state: [u32; 5],
    count: u64,
    buffer: [u8; 64],
    buf_len: usize,
}

impl Sha1 {
    fn new() -> Self {
        Self {
            state: [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0],
            count: 0,
            buffer: [0; 64],
            buf_len: 0,
        }
    }

    fn update(&mut self, data: &[u8]) {
        for &byte in data {
            self.buffer[self.buf_len] = byte;
            self.buf_len += 1;
            self.count += 1;
            if self.buf_len == 64 {
                self.process_block();
                self.buf_len = 0;
            }
        }
    }

    fn process_block(&mut self) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([
                self.buffer[i * 4],
                self.buffer[i * 4 + 1],
                self.buffer[i * 4 + 2],
                self.buffer[i * 4 + 3],
            ]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }

        let [mut a, mut b, mut c, mut d, mut e] = self.state;

        for i in 0..80 {
            let (f, k) = match i {
                0..=19 => ((b & c) | ((!b) & d), 0x5A827999),
                20..=39 => (b ^ c ^ d, 0x6ED9EBA1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8F1BBCDC),
                _ => (b ^ c ^ d, 0xCA62C1D6),
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }

        self.state[0] = self.state[0].wrapping_add(a);
        self.state[1] = self.state[1].wrapping_add(b);
        self.state[2] = self.state[2].wrapping_add(c);
        self.state[3] = self.state[3].wrapping_add(d);
        self.state[4] = self.state[4].wrapping_add(e);
    }

    fn finalize(mut self) -> [u8; 20] {
        let total_bits = self.count * 8;
        self.buffer[self.buf_len] = 0x80;
        self.buf_len += 1;

        if self.buf_len > 56 {
            while self.buf_len < 64 {
                self.buffer[self.buf_len] = 0;
                self.buf_len += 1;
            }
            self.process_block();
            self.buf_len = 0;
        }

        while self.buf_len < 56 {
            self.buffer[self.buf_len] = 0;
            self.buf_len += 1;
        }

        let bits_bytes = total_bits.to_be_bytes();
        self.buffer[56..64].copy_from_slice(&bits_bytes);
        self.process_block();

        let mut out = [0u8; 20];
        for i in 0..5 {
            out[i * 4..i * 4 + 4].copy_from_slice(&self.state[i].to_be_bytes());
        }
        out
    }
}

fn hmac_sha1(key: &[u8], data: &[u8]) -> [u8; 20] {
    let mut k = [0u8; 64];
    if key.len() > 64 {
        let mut hasher = Sha1::new();
        hasher.update(key);
        k[..20].copy_from_slice(&hasher.finalize());
    } else {
        k[..key.len()].copy_from_slice(key);
    }

    let mut ipad = [0x36u8; 64];
    let mut opad = [0x5Cu8; 64];
    for i in 0..64 {
        ipad[i] ^= k[i];
        opad[i] ^= k[i];
    }

    let mut inner = Sha1::new();
    inner.update(&ipad);
    inner.update(data);
    let inner_hash = inner.finalize();

    let mut outer = Sha1::new();
    outer.update(&opad);
    outer.update(&inner_hash);
    outer.finalize()
}

fn pbkdf2_sha1(password: &[u8], salt: &[u8], iterations: usize, output: &mut [u8]) {
    let mut block_idx = 1u32;
    let mut out_pos = 0;

    while out_pos < output.len() {
        let mut salt_idx = salt.to_vec();
        salt_idx.extend_from_slice(&block_idx.to_be_bytes());

        let mut u = hmac_sha1(password, &salt_idx);
        let mut t = u;

        for _ in 1..iterations {
            u = hmac_sha1(password, &u);
            for i in 0..20 {
                t[i] ^= u[i];
            }
        }

        let copy_len = (output.len() - out_pos).min(20);
        output[out_pos..out_pos + copy_len].copy_from_slice(&t[..copy_len]);
        out_pos += copy_len;
        block_idx += 1;
    }
}

fn main() {
    let salt = hex::decode("a35877e3ac0651f9").unwrap_or(vec![0xa3, 0x58, 0x77, 0xe3, 0xac, 0x06, 0x51, 0xf9]);
    let mut dk = [0u8; 34]; // 2 * 16 + 2
    pbkdf2_sha1(b"ab", &salt, 1000, &mut dk);
    let pvv = &dk[32..34];
    println!("Derived PVV: {:02x}{:02x}", pvv[0], pvv[1]);
}
