struct ZipCrypto {
    key0: u32,
    key1: u32,
    key2: u32,
}

impl ZipCrypto {
    fn new(password: &[u8]) -> Self {
        let mut z = Self {
            key0: 0x12345678,
            key1: 0x23456789,
            key2: 0x34567890,
        };
        for &b in password {
            z.update(b);
        }
        z
    }

    fn update(&mut self, b: u8) {
        self.key0 = crc32fast::Hasher::update_one(self.key0, b);
        self.key1 = self.key1.wrapping_add(self.key0 & 0xff).wrapping_mul(134775813).wrapping_add(1);
        self.key2 = crc32fast::Hasher::update_one(self.key2, (self.key1 >> 24) as u8);
    }

    fn decrypt_byte(&mut self, cipher_byte: u8) -> u8 {
        let temp = (self.key2 | 2) & 0xffff;
        let magic = ((temp.wrapping_mul(temp ^ 1)) >> 8) as u8;
        let plain_byte = cipher_byte ^ magic;
        self.update(plain_byte);
        plain_byte
    }
}

fn check_zipcrypto(path: &str, password: &str) -> bool {
    let data = fs::read(path).unwrap();
