    let cd_offset = u32::from_le_bytes(data[eocd+16..eocd+20].try_into().unwrap()) as usize;

    let mut pos = cd_offset;
    for _ in 0..cd_entries {
        if &data[pos..pos+4] != b"PK\x01\x02" { break; }
        let flag = u16::from_le_bytes(data[pos+8..pos+10].try_into().unwrap());
        let method = u16::from_le_bytes(data[pos+10..pos+12].try_into().unwrap());
        let crc32 = u32::from_le_bytes(data[pos+16..pos+20].try_into().unwrap());
        let fn_len = u16::from_le_bytes(data[pos+28..pos+30].try_into().unwrap()) as usize;
        let ex_len = u16::from_le_bytes(data[pos+30..pos+32].try_into().unwrap()) as usize;
        let cm_len = u16::from_le_bytes(data[pos+32..pos+34].try_into().unwrap()) as usize;
        let lfh_off = u32::from_le_bytes(data[pos+42..pos+46].try_into().unwrap()) as usize;

        if flag & 1 != 0 && method != 99 { // ZipCrypto
            let lfn_len = u16::from_le_bytes(data[lfh_off+26..lfh_off+28].try_into().unwrap()) as usize;
            let lex_len = u16::from_le_bytes(data[lfh_off+28..lfh_off+30].try_into().unwrap()) as usize;
            let payload_offset = lfh_off + 30 + lfn_len + lex_len;

            let mut zc = ZipCrypto::new(password.as_bytes());
            let mut header = [0u8; 12];
            for i in 0..12 {
                header[i] = zc.decrypt_byte(data[payload_offset + i]);
