    let dict_file_opt = matches.get_one::<String>("passwordDictionary");
    if let Some(dict_str) = dict_file_opt {
        let dict_path = Path::new(dict_str);
        if !dict_path.exists() || !dict_path.is_file() {
            eprintln!("CLI argument error - \"'passwordDictionary' does not exist\"");
            exit(1);
