fn password_to_index(password: &str, charset: &[char]) -> u128 {
    let k = charset.len() as u128;
    let mut index = 0u128;
    for c in password.chars() {
        let pos = charset.iter().position(|&x| x == c).unwrap() as u128;
        index = index * k + pos;
    }
    index
}

fn index_to_password(mut index: u128, len: usize, charset: &[char]) -> String {
    let k = charset.len() as u128;
    let mut chars = vec![' '; len];
    for i in (0..len).rev() {
        chars[i] = charset[(index % k) as usize];
        index /= k;
    }
    chars.into_iter().collect()
}

