        Ok(d) => d,
        Err(e) => {
            eprintln!("Invalid zip file error - {e}");
            exit(1);
        }
    };

    // Find EOCD
    let eocd_pos = match file_data.windows(4).rposition(|w| w == b"PK\x05\x06") {
        Some(p) => p,
        None => {
            eprintln!("Invalid zip file error - invalid Zip archive: Could not find EOCD");
            exit(1);
        }
    };

    if file_data.len() < eocd_pos + 22 {
        eprintln!("Invalid zip file error - invalid Zip archive: Could not find EOCD");
        exit(1);
    }

    let cd_entries = u16::from_le_bytes(file_data[eocd_pos + 10..eocd_pos + 12].try_into().unwrap()) as usize;
    let cd_offset = u32::from_le_bytes(file_data[eocd_pos + 16..eocd_pos + 20].try_into().unwrap()) as usize;

    let file_number_str = matches.get_one::<String>("fileNumber").unwrap();
    let file_number: usize = file_number_str.parse().unwrap_or_else(|_| exit(2));

    if file_number >= cd_entries {
        eprintln!("File number not found within archive error - '{file_number}'");
        exit(1);
    }

    // Locate CDH entry
    let mut pos = cd_offset;
    let mut target_cdh = None;

    for i in 0..cd_entries {
        if pos + 46 > file_data.len() || &file_data[pos..pos + 4] != b"PK\x01\x02" {
            break;
        }
        let fn_len = u16::from_le_bytes(file_data[pos + 28..pos + 30].try_into().unwrap()) as usize;
        let ex_len = u16::from_le_bytes(file_data[pos + 30..pos + 32].try_into().unwrap()) as usize;
        let cm_len = u16::from_le_bytes(file_data[pos + 32..pos + 34].try_into().unwrap()) as usize;

        if i == file_number {
            target_cdh = Some(pos);
            break;
        }

        pos += 46 + fn_len + ex_len + cm_len;
    }

    let cdh_off = match target_cdh {
        Some(p) => p,
        None => {
            eprintln!("File number not found within archive error - '{file_number}'");
            exit(1);
        }
    };

    let flag = u16::from_le_bytes(file_data[cdh_off + 8..cdh_off + 10].try_into().unwrap());
    let method = u16::from_le_bytes(file_data[cdh_off + 10..cdh_off + 12].try_into().unwrap());
    let time = u16::from_le_bytes(file_data[cdh_off + 12..cdh_off + 14].try_into().unwrap());
    let crc32 = u32::from_le_bytes(file_data[cdh_off + 16..cdh_off + 20].try_into().unwrap());
    let csize = u32::from_le_bytes(file_data[cdh_off + 20..cdh_off + 24].try_into().unwrap()) as usize;
    let usize_expected = u32::from_le_bytes(file_data[cdh_off + 24..cdh_off + 28].try_into().unwrap()) as usize;
    let fn_len = u16::from_le_bytes(file_data[cdh_off + 28..cdh_off + 30].try_into().unwrap()) as usize;
    let ex_len = u16::from_le_bytes(file_data[cdh_off + 30..cdh_off + 32].try_into().unwrap()) as usize;
    let lfh_off = u32::from_le_bytes(file_data[cdh_off + 42..cdh_off + 46].try_into().unwrap()) as usize;
    let file_name = String::from_utf8_lossy(&file_data[cdh_off + 46..cdh_off + 46 + fn_len]).to_string();

    if flag & 1 == 0 {
        eprintln!("Invalid zip file error - the selected file in the archive is not encrypted (file_number:{file_number} file_name:{file_name})");
        exit(1);
    }

    let lfn_len = u16::from_le_bytes(file_data[lfh_off + 26..lfh_off + 28].try_into().unwrap()) as usize;
    let lex_len = u16::from_le_bytes(file_data[lfh_off + 28..lfh_off + 30].try_into().unwrap()) as usize;
    let payload_offset = lfh_off + 30 + lfn_len + lex_len;

    let spec = if method == 99 {
        // AES encryption
        let extra = &file_data[cdh_off + 46 + fn_len..cdh_off + 46 + fn_len + ex_len];
        let mut epos = 0;
        let mut aes_mode = 3; // default 256-bit
        while epos + 4 <= extra.len() {
            let eid = u16::from_le_bytes(extra[epos..epos + 2].try_into().unwrap());
            let elen = u16::from_le_bytes(extra[epos + 2..epos + 4].try_into().unwrap()) as usize;
            if eid == 0x9901 && epos + 4 + elen <= extra.len() && elen >= 7 {
                aes_mode = extra[epos + 8];
                break;
            }
            epos += 4 + elen;
        }

        let (salt_len, key_len) = match aes_mode {
            1 => (8, 16),
            2 => (12, 24),
            _ => (16, 32),
        };

        let salt = file_data[payload_offset..payload_offset + salt_len].to_vec();
        let stored_pvv = [
            file_data[payload_offset + salt_len],
            file_data[payload_offset + salt_len + 1],
        ];

        EncryptionSpec::Aes {
            salt,
            stored_pvv,
            key_len,
        }
    } else {
        let check_byte = if flag & 8 != 0 {
            (time >> 8) as u8
        } else {
            (crc32 >> 24) as u8
        };

        EncryptionSpec::ZipCrypto {
            payload_offset,
            csize,
            usize_expected,
            method,
            check_byte,
            crc32,
        }
    };

    let verify_password = Arc::new(move |pwd: &str| -> bool {
        match &spec {
            EncryptionSpec::Aes {
                salt,
                stored_pvv,
                key_len,
            } => {
                let mut dk = vec![0u8; 2 * key_len + 2];
                pbkdf2_sha1(pwd.as_bytes(), salt, 1000, &mut dk);
                let pvv = [dk[2 * key_len], dk[2 * key_len + 1]];
                pvv == *stored_pvv
            }
            EncryptionSpec::ZipCrypto {
                payload_offset,
                csize,
                usize_expected,
                method,
                check_byte,
                crc32,
            } => {
                let payload = &file_data[*payload_offset..*payload_offset + *csize];
                if payload.len() < 12 {
                    return false;
                }
                let mut zc = ZipCrypto::new(pwd.as_bytes());
                let mut hdr_check = 0u8;
                for i in 0..12 {
                    hdr_check = zc.decrypt_byte(payload[i]);
                }
                if hdr_check != *check_byte {
                    return false;
                }

                if *csize <= 12 {
                    return true;
                }

                let encrypted_content = &payload[12..];
                let mut decrypted = Vec::with_capacity(encrypted_content.len());
                for &b in encrypted_content {
                    decrypted.push(zc.decrypt_byte(b));
                }

                if *method == 0 {
                    // Stored
                    if decrypted.len() != *usize_expected {
                        return false;
                    }
                    crc32fast::hash(&decrypted) == *crc32
                } else if *method == 8 {
                    // Deflate
                    let mut decoder = flate2::read::DeflateDecoder::new(&decrypted[..]);
                    let mut decompressed = Vec::new();
                    if decoder.read_to_end(&mut decompressed).is_ok() {
                        decompressed.len() == *usize_expected && crc32fast::hash(&decompressed) == *crc32
                    } else {
                        false
                    }
                } else {
                    true
                }
            }
        }
    });

    let num_workers = workers_opt.unwrap_or_else(|| {
        thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    });

    let start_time = Instant::now();
    let found_password = Arc::new(Mutex::new(None));
    let stop_flag = Arc::new(AtomicBool::new(false));

    if let Some(dict_file) = dict_file_opt {
        let content = fs::read_to_string(dict_file).unwrap_or_default();
        let lines: Vec<String> = content
            .lines()
            .map(|l| l.trim_end_matches('\r').to_string())
            .collect();

        let lines_arc = Arc::new(lines);
        let current_index = Arc::new(AtomicUsize::new(0));

        let mut handles = Vec::new();
        for i in 0..num_workers {
            let verify = Arc::clone(&verify_password);
            let lines_ref = Arc::clone(&lines_arc);
            let index_ref = Arc::clone(&current_index);
            let found_ref = Arc::clone(&found_password);
            let stop_ref = Arc::clone(&stop_flag);

            let builder = thread::Builder::new().name(format!("worker-{}", i + 1));
            let handle = builder
                .spawn(move || {
                    while !stop_ref.load(Ordering::Relaxed) {
                        let idx = index_ref.fetch_add(100, Ordering::Relaxed);
                        if idx >= lines_ref.len() {
                            break;
                        }
                        let end = (idx + 100).min(lines_ref.len());
                        for j in idx..end {
                            if stop_ref.load(Ordering::Relaxed) {
                                break;
                            }
                            if verify(&lines_ref[j]) {
                                let mut f = found_ref.lock().unwrap();
                                if f.is_none() {
                                    *f = Some(lines_ref[j].clone());
                                }
                                stop_ref.store(true, Ordering::SeqCst);
                                break;
                            }
                        }
                    }
                })
                .unwrap();
            handles.push(handle);
        }

        for h in handles {
            let _ = h.join();
        }
    } else {
        assert!(!charset_vec.is_empty(), "charset non empty");

        let charset_arc = Arc::new(charset_vec);

        for len in min_len..=max_len {
            if stop_flag.load(Ordering::Relaxed) {
                break;
            }

            let start_idx = if let Some(start_pwd) = starting_pwd_opt {
                let start_len = start_pwd.len();
                if len < start_len {
                    continue;
                } else if len == start_len {
                    password_to_index(start_pwd, &charset_arc)
                } else {
                    0u128
                }
            } else {
                0u128
            };

            let k = charset_arc.len() as u128;
            let total_passwords = k.pow(len as u32);
            if start_idx >= total_passwords {
                continue;
            }

            let current_index = Arc::new(Mutex::new(start_idx));

            let mut handles = Vec::new();
            for i in 0..num_workers {
                let verify = Arc::clone(&verify_password);
                let charset_ref = Arc::clone(&charset_arc);
                let index_ref = Arc::clone(&current_index);
                let found_ref = Arc::clone(&found_password);
                let stop_ref = Arc::clone(&stop_flag);

                let builder = thread::Builder::new().name(format!("worker-{}", i + 1));
                let handle = builder
                    .spawn(move || {
                        while !stop_ref.load(Ordering::Relaxed) {
                            let chunk_size = 1000u128;
                            let idx = {
                                let mut guard = index_ref.lock().unwrap();
                                let val = *guard;
                                *guard = guard.saturating_add(chunk_size);
                                val
                            };
                            if idx >= total_passwords {
                                break;
                            }
                            let end = (idx + chunk_size).min(total_passwords);
                            for j in idx..end {
                                if stop_ref.load(Ordering::Relaxed) {
                                    break;
                                }
                                let pwd = index_to_password(j, len, &charset_ref);
                                if verify(&pwd) {
                                    let mut f = found_ref.lock().unwrap();
                                    if f.is_none() {
                                        *f = Some(pwd);
                                    }
                                    stop_ref.store(true, Ordering::SeqCst);
                                    break;
                                }
                            }
                        }
                    })
                    .unwrap();
                handles.push(handle);
            }

            for h in handles {
                let _ = h.join();
            }
        }
    }

    let duration = start_time.elapsed();
    println!("Time elapsed: {}", format_duration(duration));

    let f = found_password.lock().unwrap();
    if let Some(ref pwd) = *f {
        println!("Password found:{pwd}");
    } else {
        println!("Password not found");
    }
}
EOF
"}
